1 | #!/usr/bin/env node
2 | /* recompute_core.js — rebuild the growth-core `coreRank` via the growth_core ruleset engine.
3 |  *
4 |  * Usage:  node scripts/recompute_core.js <core_metrics.json> [--pretty]
5 |  *
6 |  * Input JSON (assembled by the daily task from the connector + universe rows):
7 |  *   { "NVDA": {roe,roa,gm,nm,pe,ev,trend,upside, off?, cross?, held?}, "GOOG": {...}, ... }
8 |  *   - roe/roa/gm/nm/pe/ev  : company fundamentals (fractions for margins/roe; ratios for pe/ev)
9 |  *   - trend                : 0.5*%vs200d + 0.5*%vs50d (from the universe row)
10 |  *   - upside               : analyst target/price - 1
11 |  *   - off, cross, held     : passthrough for the card (off-high, "Golden"/"Death", holding flag)
12 |  *
13 |  * Prints the new coreRank array (rank,ticker,comp,Q,V,T,A,pe,off,cross,up,held) as JSON to stdout.
14 |  * On unreadable/empty input, exits non-zero so the caller can PRESERVE the prior coreRank (never blank).
15 |  */
16 | const fs = require("fs"), path = require("path");
17 | const BASE = path.dirname(__dirname);
18 | const engine = require(path.join(BASE, "src", "ranking", "engine.js"));
19 | const RS = require(path.join(BASE, "src", "ranking", "rulesets", "growth_core.json"));
20 | 
21 | const inPath = process.argv[2];
22 | if (!inPath) { console.error("usage: recompute_core.js <core_metrics.json> [--pretty]"); process.exit(1); }
23 | let metrics;
24 | try { metrics = JSON.parse(fs.readFileSync(inPath, "utf8")); } catch (e) { console.error("cannot read metrics: " + e.message); process.exit(2); }
25 | const tickers = Object.keys(metrics || {});
26 | if (!tickers.length) { console.error("no tickers in metrics"); process.exit(2); }
27 | 
28 | const items = tickers.map(t => ({ id: t, metrics: {
29 |   roe: metrics[t].roe, roa: metrics[t].roa, gm: metrics[t].gm, nm: metrics[t].nm,
30 |   pe: metrics[t].pe, ev: metrics[t].ev, trend: metrics[t].trend, upside: metrics[t].upside } }));

